+$script:ConfigKeys = @('dataFile', 'defaultJson')
+
+function Read-ConfigStore {
+    param([Parameter(Mandatory)][string]$Path)
+
+    $config = [ordered]@{}
+    if (-not (Test-Path -LiteralPath $Path)) {
+        return $config
+    }
+
+    $content = Get-Content -LiteralPath $Path -Raw
+    if ([string]::IsNullOrWhiteSpace($content)) {
+        return $config
+    }
+
+    $parsed = ConvertFrom-Json -InputObject $content
+    foreach ($key in $script:ConfigKeys) {
+        if ($parsed.PSObject.Properties.Name -contains $key) {
+            $config[$key] = $parsed.$key
+        }
+    }
+    return $config
+}
+
+function Write-ConfigStore {
+    param(
+        [Parameter(Mandatory)][string]$Path,
+        [Parameter(Mandatory)][System.Collections.IDictionary]$Config
+    )
+
+    $parent = Split-Path -Parent $Path
+    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
+        New-Item -ItemType Directory -Path $parent -Force | Out-Null
+    }
+
+    $ordered = [ordered]@{}
+    foreach ($key in $script:ConfigKeys) {
+        if ($Config.Contains($key)) {
+            $ordered[$key] = $Config[$key]
+        }
+    }
+
+    $temporary = "$Path.$PID.tmp"
+    $json = ConvertTo-Json -InputObject ([pscustomobject]$ordered) -Depth 8
+    [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
+    Move-Item -LiteralPath $temporary -Destination $Path -Force
+}
+
+function Resolve-ConfigPath {
+    param(
+        [Parameter(Mandatory)][string]$ConfigFile,
+        [Parameter(Mandatory)][string]$Value
+    )
+
+    if ([System.IO.Path]::IsPathRooted($Value)) {
+        return $Value
+    }
+    $directory = Split-Path -Parent $ConfigFile
+    if ([string]::IsNullOrEmpty($directory)) {
+        $directory = '.'
+    }
+    return (Join-Path $directory $Value)
+}
+
+function ConvertTo-ConfigBoolean {
+    param([Parameter(Mandatory)]$Value)
+
+    if ($Value -is [bool]) {
+        return [bool]$Value
+    }
+    switch (([string]$Value).Trim().ToLowerInvariant()) {
+        'true' { return $true }
+        'false' { return $false }
+        default { throw "Invalid boolean value for defaultJson: '$Value'. Use 'true' or 'false'." }
+    }
+}
+
+function Format-ConfigValue {
+    param($Value)
+
+    if ($null -eq $Value) {
+        return ''
+    }
+    if ($Value -is [bool]) {
+        return $(if ($Value) { 'true' } else { 'false' })
+    }
+    return [string]$Value
+}
+
+function ConvertFrom-ConfigArguments {
+    param([AllowEmptyCollection()][string[]]$Arguments)
+
+    $positionals = [System.Collections.Generic.List[string]]::new()
+    $options = [ordered]@{}
+    for ($index = 0; $index -lt $Arguments.Count; $index++) {
+        $token = $Arguments[$index]
+        if ($token.StartsWith('--')) {
+            $name = $token.Substring(2)
+            if ([string]::IsNullOrWhiteSpace($name)) {
+                throw 'Option name cannot be empty.'
+            }
+            if ($options.Contains($name)) {
+                throw "Duplicate option: --$name"
+            }
+            if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
+                $options[$name] = $Arguments[++$index]
+            }
+            else {
+                $options[$name] = $true
+            }
+        }
+        else {
+            $positionals.Add($token)
+        }
+    }
+
+    return [pscustomobject]@{
+        Positionals = @($positionals)
+        Options = $options
+    }
+}
+
 function ConvertFrom-TaskForgeArguments {
     param([AllowEmptyCollection()][string[]]$Arguments)

